    const ICBTop = document.body.getBoundingClientRect().top - parseInt(getComputedStyle(document.body).marginTop.slice(0, -2)) + document.body.scrollTop;
    let yPos = 0;
    for(el of getOffsetParents(el)) {
        // offsetTop = distance from offsetParent's padding edge
        //             to your border edge
        // scrollTop = if you have a scroller, how much it's been scrolled
        // clientTop = distance from your border edge to your padding edge
        // As defined, summing these should give you the distance between
        // your padding edge and your offsetParent's padding edge
        yPos += (el.offsetTop - el.scrollTop + el.offsetParent.clientTop);
