        log(`gBCR()-based offset to ICB: ${Math.round(el.getBoundingClientRect().top - ICBTop - el.scrollTop)}px`)
    }
}
function getOffsetParents(el) {
    // Return offsetParent chain, in reverse order (root to el)
    const offsets = [];
