`UniFFIPointer::Read` and `::Write()` (`toolkit/components/uniffi-js/UniFFIPointer.cpp`) use `CheckedInt` incorrectly, potentially allowing out-of-bounds accesses. I do not have a POC as I'm unsure how this code is used. The bugs are on lines 47 and 77, which compute a sum using unprotected `uint32_t` math, then assign the potentially-overflowed result to a `CheckedInt32`. The code then checks that value for validity and range, but it will always be valid, and it is likely to be in range if an overflow occurred. (code from `FIREFOX_122_0_RELEASE`):

```
    37: already_AddRefed<UniFFIPointer> UniFFIPointer::Read(
    38:     const ArrayBuffer& aArrayBuff, uint32_t aPosition,
    39:     const UniFFIPointerType* aType, ErrorResult& aError) {
    40:   MOZ_LOG(sUniFFIPointerLogger, LogLevel::Info,
    41:           ("[UniFFI] Reading Pointer from buffer"));
    42: 
    43:   uint8_t data_ptr[8];
    44:   if (!aArrayBuff.CopyDataTo(
    45:           data_ptr,
    46:           [aPosition](size_t aLength) -> Maybe<std::pair<size_t, size_t>> {
    47:             CheckedUint32 end = aPosition + 8;
    48:             if (!end.isValid() || end.value() > aLength) {
    49:               return Nothing();
    50:             }
    51:             return Some(std::make_pair(aPosition, 8));
    52:           })) {
    53:     aError.ThrowRangeError("position is out of range");
    54:     return nullptr;
    55:   }
    56: 
    57:   // in Rust and Write(), a pointer is converted to a void* then written as u64
    58:   // BigEndian we do the reverse here
    59:   void* ptr = (void*)mozilla::BigEndian::readUint64(data_ptr);
    60:   return UniFFIPointer::Create(ptr, aType);
    61: }
    62: 
    63: void UniFFIPointer::Write(const ArrayBuffer& aArrayBuff, uint32_t aPosition,
    64:                           const UniFFIPointerType* aType,
    65:                           ErrorResult& aError) const {
    66:   if (!this->IsSamePtrType(aType)) {
    67:     aError.ThrowUnknownError(nsPrintfCString(
    68:         "Attempt to write pointer with wrong type: %s (expected: %s)",
    69:         aType->typeName.get(), this->mType->typeName.get()));
    70:     return;
    71:   }
    72:   MOZ_LOG(sUniFFIPointerLogger, LogLevel::Info,
    73:           ("[UniFFI] Writing Pointer to buffer"));
    74: 
    75:   aArrayBuff.ProcessData([&](const Span<uint8_t>& aData,
    76:                              JS::AutoCheckCannotGC&&) {
    77:     CheckedUint32 end = aPosition + 8;
    78:     if (!end.isValid() || end.value() > aData.Length()) {
    79:       aError.ThrowRangeError("position is out of range");
    80:       return;
    81:     }
    82:     // in Rust and Read(), a u64 is read as BigEndian and then converted to
    83:     // a pointer we do the reverse here
    84:     const auto& data_ptr = aData.Subspan(aPosition, 8);
    85:     mozilla::BigEndian::writeUint64(data_ptr.Elements(), (uint64_t)GetPtr());
    86:   });
    87: }
```

